package dev.mesbase.infrastructure.platform;
import org.apache.ibatis.annotations.*;
import java.util.List;
import dev.mesbase.infrastructure.persistence.PersistenceOwner;
import dev.mesbase.infrastructure.platform.PlatformRows.*;
@PersistenceOwner(PersistenceOwner.Kind.PLATFORM)
public interface PlatformMapper {
 @Select("SELECT id AS id,username AS username,display_name AS displayName,password_hash AS passwordHash,status AS status,created_at AS createdAt FROM sys_user WHERE id=#{id}") User findUser(String id);
 @Select("SELECT id AS id,username AS username,display_name AS displayName,password_hash AS passwordHash,status AS status,created_at AS createdAt FROM sys_user ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<User> listUser(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_user(id,username,display_name,password_hash,status,created_at) VALUES(#{id},#{username},#{displayName},#{passwordHash},#{status},#{createdAt})") int insertUser(User row);
 @Update("UPDATE sys_user SET username=#{username},display_name=#{displayName},password_hash=#{passwordHash},status=#{status},created_at=#{createdAt} WHERE id=#{id}") int updateUser(User row);
 @Delete("DELETE FROM sys_user WHERE id=#{id}") int deleteUser(String id);
 @Select("SELECT id AS id,name AS name,kind AS kind,factory_id AS factoryId,status AS status FROM sys_role WHERE id=#{id}") Role findRole(String id);
 @Select("SELECT id AS id,name AS name,kind AS kind,factory_id AS factoryId,status AS status FROM sys_role ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<Role> listRole(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_role(id,name,kind,factory_id,status) VALUES(#{id},#{name},#{kind},#{factoryId,jdbcType=VARCHAR},#{status})") int insertRole(Role row);
 @Update("UPDATE sys_role SET name=#{name},kind=#{kind},factory_id=#{factoryId,jdbcType=VARCHAR},status=#{status} WHERE id=#{id}") int updateRole(Role row);
 @Delete("DELETE FROM sys_role WHERE id=#{id}") int deleteRole(String id);
 @Select("SELECT id AS id,parent_id AS parentId,name AS name,path AS path,permission AS permission,sort_order AS sortOrder,kind AS kind FROM sys_menu WHERE id=#{id}") Menu findMenu(String id);
 @Select("SELECT id AS id,parent_id AS parentId,name AS name,path AS path,permission AS permission,sort_order AS sortOrder,kind AS kind FROM sys_menu ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<Menu> listMenu(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_menu(id,parent_id,name,path,permission,sort_order,kind) VALUES(#{id},#{parentId},#{name},#{path},#{permission},#{sortOrder},#{kind})") int insertMenu(Menu row);
 @Update("UPDATE sys_menu SET parent_id=#{parentId},name=#{name},path=#{path},permission=#{permission},sort_order=#{sortOrder},kind=#{kind} WHERE id=#{id}") int updateMenu(Menu row);
 @Delete("DELETE FROM sys_menu WHERE id=#{id}") int deleteMenu(String id);
 @Select("SELECT id AS id,code AS code,name AS name FROM sys_dict_type WHERE id=#{id}") DictType findDictType(String id);
 @Select("SELECT id AS id,code AS code,name AS name FROM sys_dict_type ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<DictType> listDictType(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_dict_type(id,code,name) VALUES(#{id},#{code},#{name})") int insertDictType(DictType row);
 @Update("UPDATE sys_dict_type SET code=#{code},name=#{name} WHERE id=#{id}") int updateDictType(DictType row);
 @Delete("DELETE FROM sys_dict_type WHERE id=#{id}") int deleteDictType(String id);
 @Select("SELECT id AS id,type_id AS typeId,dict_value AS dictValue,label AS label,sort_order AS sortOrder FROM sys_dict_data WHERE id=#{id}") DictData findDictData(String id);
 @Select("SELECT id AS id,type_id AS typeId,dict_value AS dictValue,label AS label,sort_order AS sortOrder FROM sys_dict_data ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<DictData> listDictData(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_dict_data(id,type_id,dict_value,label,sort_order) VALUES(#{id},#{typeId},#{value},#{label},#{sortOrder})") int insertDictData(DictData row);
 @Update("UPDATE sys_dict_data SET type_id=#{typeId},dict_value=#{value},label=#{label},sort_order=#{sortOrder} WHERE id=#{id}") int updateDictData(DictData row);
 @Delete("DELETE FROM sys_dict_data WHERE id=#{id}") int deleteDictData(String id);
 @Select("SELECT id AS id,config_key AS configKey,config_value AS configValue,kind AS kind,factory_id AS factoryId FROM sys_config WHERE id=#{id}") Config findConfig(String id);
 @Select("SELECT id AS id,config_key AS configKey,config_value AS configValue,kind AS kind,factory_id AS factoryId FROM sys_config ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<Config> listConfig(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_config(id,config_key,config_value,kind,factory_id,scope_key) VALUES(#{id},#{configKey},#{configValue},#{kind},#{factoryId,jdbcType=VARCHAR},CASE WHEN #{kind}='GLOBAL' THEN 'PLATFORM' ELSE CONCAT('FACTORY:',#{factoryId,jdbcType=VARCHAR}) END)") int insertConfig(Config row);
 @Update("UPDATE sys_config SET scope_key=CASE WHEN #{kind}='GLOBAL' THEN 'PLATFORM' ELSE CONCAT('FACTORY:',#{factoryId,jdbcType=VARCHAR}) END,config_key=#{configKey},config_value=#{configValue},kind=#{kind},factory_id=#{factoryId,jdbcType=VARCHAR} WHERE id=#{id}") int updateConfig(Config row);
 @Delete("DELETE FROM sys_config WHERE id=#{id}") int deleteConfig(String id);
 @Select("SELECT id AS id,name AS name,handler AS handler,execution_scope AS executionScope,factory_id AS factoryId,cron AS cron,status AS status,running_token AS runningToken,started_at AS startedAt FROM sys_job WHERE id=#{id}") Job findJob(String id);
 @Select("SELECT id AS id,name AS name,handler AS handler,execution_scope AS executionScope,factory_id AS factoryId,cron AS cron,status AS status,running_token AS runningToken,started_at AS startedAt FROM sys_job ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<Job> listJob(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_job(id,name,handler,execution_scope,factory_id,cron,status,running_token,started_at) VALUES(#{id},#{name},#{handler},#{executionScope},#{factoryId,jdbcType=VARCHAR},#{cron},#{status},#{runningToken},#{startedAt})") int insertJob(Job row);
 @Update("UPDATE sys_job SET name=#{name},handler=#{handler},execution_scope=#{executionScope},factory_id=#{factoryId,jdbcType=VARCHAR},cron=#{cron},status=#{status},running_token=#{runningToken},started_at=#{startedAt} WHERE id=#{id} AND running_token IS NULL") int updateJob(Job row);
 @Delete("DELETE FROM sys_job WHERE id=#{id} AND running_token IS NULL") int deleteJob(String id);
 @Select("SELECT id AS id,request_id AS requestId,actor_id AS actorId,factory_id AS factoryId,execution_scope AS executionScope,action AS action,outcome AS outcome,created_at AS createdAt FROM sys_oper_log WHERE id=#{id}") Audit findAudit(String id);
 @Select("SELECT id AS id,request_id AS requestId,actor_id AS actorId,factory_id AS factoryId,execution_scope AS executionScope,action AS action,outcome AS outcome,created_at AS createdAt FROM sys_oper_log ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<Audit> listAudit(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_oper_log(id,request_id,actor_id,factory_id,execution_scope,action,outcome,created_at) VALUES(#{id},#{requestId},#{actorId},#{factoryId,jdbcType=VARCHAR},#{executionScope},#{action},#{outcome},#{createdAt})") int insertAudit(Audit row);
 @Select("SELECT id AS id,request_id AS requestId,actor_id AS actorId,factory_id AS factoryId,execution_scope AS executionScope,outcome AS outcome,created_at AS createdAt FROM sys_logininfor WHERE id=#{id}") LoginLog findLoginLog(String id);
 @Select("SELECT id AS id,request_id AS requestId,actor_id AS actorId,factory_id AS factoryId,execution_scope AS executionScope,outcome AS outcome,created_at AS createdAt FROM sys_logininfor ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<LoginLog> listLoginLog(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_logininfor(id,request_id,actor_id,factory_id,execution_scope,outcome,created_at) VALUES(#{id},#{requestId},#{actorId},#{factoryId,jdbcType=VARCHAR},#{executionScope},#{outcome},#{createdAt})") int insertLoginLog(LoginLog row);
 @Select("SELECT id AS id,job_id AS jobId,request_id AS requestId,actor_id AS actorId,factory_id AS factoryId,execution_scope AS executionScope,outcome AS outcome,created_at AS createdAt FROM sys_job_log WHERE id=#{id}") JobLog findJobLog(String id);
 @Select("SELECT id AS id,job_id AS jobId,request_id AS requestId,actor_id AS actorId,factory_id AS factoryId,execution_scope AS executionScope,outcome AS outcome,created_at AS createdAt FROM sys_job_log ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<JobLog> listJobLog(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_job_log(id,job_id,request_id,actor_id,factory_id,execution_scope,outcome,created_at) VALUES(#{id},#{jobId},#{requestId},#{actorId},#{factoryId,jdbcType=VARCHAR},#{executionScope},#{outcome},#{createdAt})") int insertJobLog(JobLog row);
 @Select("SELECT id AS id,owner_id AS ownerId,factory_id AS factoryId,resource AS resource,original_name AS originalName,size AS size,created_at AS createdAt FROM sys_file WHERE id=#{id}") File findFile(String id);
 @Select("SELECT id AS id,owner_id AS ownerId,factory_id AS factoryId,resource AS resource,original_name AS originalName,size AS size,created_at AS createdAt FROM sys_file ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<File> listFile(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_file(id,owner_id,factory_id,resource,original_name,size,created_at) VALUES(#{id},#{ownerId},#{factoryId,jdbcType=VARCHAR},#{resource},#{originalName},#{size},#{createdAt})") int insertFile(File row);
 @Select("SELECT id AS id,user_id AS userId,expires_at AS expiresAt FROM sys_session WHERE id=#{id}") Session findSession(String id);
 @Select("SELECT id AS id,user_id AS userId,expires_at AS expiresAt FROM sys_session ORDER BY id LIMIT #{limit} OFFSET #{offset}") List<Session> listSession(@Param("offset") int offset,@Param("limit") int limit);
 @Insert("INSERT INTO sys_session(id,user_id,expires_at) VALUES(#{id},#{userId},#{expiresAt})") int insertSession(Session row);
 @Select("SELECT id,username,display_name AS displayName,password_hash AS passwordHash,status,created_at AS createdAt FROM sys_user WHERE username=#{username}") User userByUsername(String username);
 @Select("SELECT r.id,r.name,r.kind,r.factory_id AS factoryId,r.status FROM sys_role r JOIN sys_user_role ur ON ur.role_id=r.id WHERE ur.user_id=#{userId} AND r.status='ENABLED'") List<Role> roles(String userId);
 @Select("SELECT m.permission FROM sys_menu m JOIN sys_role_menu rm ON rm.menu_id=m.id WHERE rm.role_id=#{roleId}") List<String> permissions(String roleId);
 @Select("SELECT DISTINCT m.id,m.parent_id AS parentId,m.name,m.path,m.permission,m.sort_order AS sortOrder,m.kind FROM sys_menu m JOIN sys_role_menu rm ON rm.menu_id=m.id JOIN sys_role r ON r.id=rm.role_id JOIN sys_user_role ur ON ur.role_id=r.id WHERE ur.user_id=#{userId} AND r.status='ENABLED' AND ((r.kind='PLATFORM' AND #{factoryId,jdbcType=VARCHAR} IS NULL) OR (r.kind='FACTORY' AND r.factory_id=#{factoryId,jdbcType=VARCHAR})) ORDER BY m.sort_order,m.id") List<Menu> grantedMenus(@Param("userId") String userId,@Param("factoryId") String factoryId);
 @Select("SELECT COUNT(*) FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id JOIN sys_role_menu rm ON rm.role_id=r.id JOIN sys_menu m ON m.id=rm.menu_id JOIN sys_user u ON u.id=ur.user_id WHERE u.username=#{username} AND u.status='ENABLED' AND r.status='ENABLED' AND m.permission=#{permission} AND ((#{factoryId,jdbcType=VARCHAR} IS NULL AND r.kind='PLATFORM') OR (r.kind='FACTORY' AND r.factory_id=#{factoryId,jdbcType=VARCHAR}))") int granted(@Param("username") String username,@Param("factoryId") String factoryId,@Param("permission") String permission);
 @Delete("DELETE FROM sys_user_role WHERE user_id=#{userId}") int clearUserRoles(String userId);
 @Insert("INSERT INTO sys_user_role(user_id,role_id) VALUES(#{userId},#{roleId})") int linkUserRole(@Param("userId") String userId,@Param("roleId") String roleId);
 @Delete("DELETE FROM sys_role_menu WHERE role_id=#{roleId}") int clearRoleMenus(String roleId);
 @Insert("INSERT INTO sys_role_menu(role_id,menu_id) VALUES(#{roleId},#{menuId})") int linkRoleMenu(@Param("roleId") String roleId,@Param("menuId") String menuId);
 @Delete("DELETE FROM sys_session WHERE id=#{hash}") int revoke(String hash);
 @Delete("DELETE FROM sys_session WHERE user_id=#{userId}") int revokeUser(String userId);
 @Select("SELECT id,type_id AS typeId,dict_value AS dictValue,label,sort_order AS sortOrder FROM sys_dict_data WHERE type_id=#{typeId} ORDER BY sort_order,id LIMIT 1001") List<DictData> dictValues(String typeId);
 @Select("SELECT id,code,name FROM sys_dict_type WHERE code=#{code}") DictType typeByCode(String code);
 @Select("SELECT id,config_key AS configKey,config_value AS configValue,kind,factory_id AS factoryId FROM sys_config WHERE scope_key=#{scopeKey} AND config_key=#{key}") Config configByKey(@Param("scopeKey") String scopeKey,@Param("key") String key);
 @Update("UPDATE sys_config SET scope_key=#{scopeKey} WHERE id=#{id}") int configScopeKey(@Param("id") String id,@Param("scopeKey") String scopeKey);
 @Update("UPDATE sys_job SET running_token=#{token},started_at=#{now} WHERE id=#{id} AND running_token IS NULL") int claimJob(@Param("id") String id,@Param("token") String token,@Param("now") java.time.LocalDateTime now);
 @Update("UPDATE sys_job SET running_token=NULL,started_at=NULL WHERE id=#{id} AND running_token=#{token}") int releaseJob(@Param("id") String id,@Param("token") String token);
 @Update("UPDATE sys_job SET running_token=NULL,started_at=NULL WHERE running_token IS NOT NULL AND started_at < #{cutoff}") int recoverJobs(java.time.LocalDateTime cutoff);
 @Select("<script>SELECT COUNT(*) FROM sys_role WHERE id IN <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach></script>") int countRoles(@Param("ids") java.util.List<String> ids);
 @Select("<script>SELECT COUNT(*) FROM sys_menu WHERE id IN <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach></script>") int countMenus(@Param("ids") java.util.List<String> ids);
 @Insert("<script>INSERT INTO sys_user_role(user_id,role_id) VALUES <foreach collection='ids' item='id' separator=','>(#{owner},#{id})</foreach></script>") int batchUserRoles(@Param("owner") String owner,@Param("ids") java.util.List<String> ids);
 @Insert("<script>INSERT INTO sys_role_menu(role_id,menu_id) VALUES <foreach collection='ids' item='id' separator=','>(#{owner},#{id})</foreach></script>") int batchRoleMenus(@Param("owner") String owner,@Param("ids") java.util.List<String> ids);
 @Select("SELECT COUNT(*) FROM sys_user") long countUser();
 @Select("SELECT COUNT(*) FROM sys_role") long countRole();
 @Select("SELECT COUNT(*) FROM sys_menu") long countMenu();
 @Select("SELECT COUNT(*) FROM sys_dict_type") long countDictType();
 @Select("SELECT COUNT(*) FROM sys_dict_data") long countDictData();
 @Select("SELECT COUNT(*) FROM sys_config") long countConfig();
 @Select("SELECT COUNT(*) FROM sys_oper_log") long countAudit();
 @Select("SELECT COUNT(*) FROM sys_logininfor") long countLoginLog();
 @Select("SELECT COUNT(*) FROM sys_job_log") long countJobLog();
 @Select("SELECT COUNT(*) FROM sys_job") long countJob();
 @Select("SELECT role_id FROM sys_user_role WHERE user_id=#{id} ORDER BY role_id LIMIT 201") java.util.List<String> userRoleIds(String id);
 @Select("SELECT menu_id FROM sys_role_menu WHERE role_id=#{id} ORDER BY menu_id LIMIT 201") java.util.List<String> roleMenuIds(String id);
 @Select("SELECT revision FROM platform_catalog_revision WHERE id=1") long catalogRevision();
 @Update("UPDATE platform_catalog_revision SET revision=revision+1 WHERE id=1") int bumpCatalogRevision();
}
